# Builds adnesia.exe as a no-console (tray) app with the Explorer icon.
#
# Run from the repo root:  powershell -ExecutionPolicy Bypass -File build.ps1
#
# Fully offline: the icon resource is generated by our own stdlib tool
# (tools/mksyso), and the build uses the vendored dependencies.

$ErrorActionPreference = "Stop"
Set-Location $PSScriptRoot
$env:GOFLAGS = "-mod=vendor"

# 1) Generate the .exe icon resource from the .ico (our own generator).
go run .\tools\mksyso Adnesia_EXE_Icon.ico cmd\adnesia\rsrc_windows.syso

# 2) Build with the GUI subsystem (no console window) and stamp the build
#    time into the dashboard footer, so it's always clear which copy runs.
$stamp = Get-Date -Format "yyyy-MM-dd_HH.mm"
go build -ldflags "-H windowsgui -X main.build=$stamp" -o adnesia.exe .\cmd\adnesia
Write-Host "Built adnesia.exe (no console window, tray + exe icon, build $stamp)."
